	guide, ok := sandboxScenarioByName(scenario)
	if !ok {
		return payload, fmt.Errorf("invalid sandbox scenario %q: supported scenarios are %s", scenario, strings.Join(sandboxScenarioNames(), ", "))
	}
	payload.Scenario = guide.Name
	payload.ScenarioGuide = &guide
